-- «Կարգեր և վարքեր»-ի եղած բաժինները (ստեղծված է scripts/guides-seed/make-seed.ts-ով). բոլորը՝ «Ստուգման մեջ»։
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('etiquette', 'Վարք եկեղեցում', 'Ինչպես մտնել, մոմ վառել, կանգնել Պատարագին, հաղորդվել', '', 'link', '/church/etiquette', 'church', '{"blocks":[],"faq":[]}', '[]', 'review', 10);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('sacraments', 'Յոթ խորհուրդներ', 'Մկրտություն, Դրոշմ, Ապաշխարություն, Հաղորդություն, Պսակ, Կարգ հիվանդաց, Ձեռնադրություն', 'Խորհուրդները Եկեղեցու սուրբ արարողություններն են, որոնցով Աստված Իր անտեսանելի շնորհը տալիս է մեզ տեսանելի նշանների միջոցով։ Հայ Առաքելական Եկեղեցին ունի յոթ խորհուրդ։', 'guide', '', 'sparkles', '{"blocks":[{"id":"mkrtutyun","title":"Մկրտություն","text":"Մկրտությունն առաջին խորհուրդն է, որին արժանանում է քրիստոնյան։ Դրանով մարդը մաքրվում է մեղքերից, վերածնվում Սուրբ Հոգով և դառնում Աստծո որդեգիր։ Մինչև չմկրտվենք, չենք կարող մյուս խորհուրդները ստանալ։\nՔահանան օրհնում է ավազանի ջուրը և մկրտվողին երեք անգամ ընկղմում ջրի մեջ կամ երեք անգամ ջուր հեղում նրա գլխին՝ Հոր և Որդու և Սուրբ Հոգու անունով։ Մկրտության համար պետք է կնքահայր, ով երաշխավորում է մկրտվողի հավատը և օգնում է դաստիարակել նրան։\nՄկրտությունը չի կրկնվում. մարդ մեկ անգամ է ծնվում նաև հոգևոր կյանքի համար։ Հայ Եկեղեցին ընդունում է այն եկեղեցիների մկրտությունը, որոնք մկրտում են Սուրբ Երրորդության անունով և կատարում դրոշմ։","when":"Մեկ անգամ՝ կյանքում, սովորաբար մանկության տարիքում","why":"Քրիստոս ասաց. «Եթե մեկը ջրից ու Հոգուց չծնվի, չի կարող Աստծու արքայությունը մտնել» (Հովհ. 3.5)։ Նա Ինքը մկրտվեց Հորդանանում և պատվիրեց աշակերտներին՝ մկրտել բոլոր ազգերին Հոր և Որդու և Սուրբ Հոգու անունով (Մատթ. 28.19)։ Երեք ընկղմումը հիշեցնում է այն երեք օրը, որ Քրիստոս մնաց գերեզմանում։"},{"id":"droshm","title":"Դրոշմ","text":"Դրոշմը (կնունքը) խորհուրդ է, որով մկրտվածը օծվում է սուրբ Մյուռոնով և ստանում Սուրբ Հոգու պարգևները։ Քահանան մյուռոնով խաչանշում է ճակատը, աչքերը, ականջները, հոտոտելիքը, բերանը, ձեռքերը, սիրտը, մեջքը և ոտքերը, և ամեն մեկի համար աղոթք է ասում։ Օրինակ՝ աչքերի համար. «Այս կնիքը Հիսուս Քրիստոսի անունով թող լուսավորի աչքերդ, որպեսզի երբեք մահ չտեսնես»։\nՄյուռոնը պատրաստվում է ձիթապտղի ձեթից և անուշահոտ նյութերից։ Այն օրհնում են միայն Ամենայն Հայոց և Մեծի Տանն Կիլիկիո կաթողիկոսները՝ յոթ տարին մեկ։","when":"Անմիջապես մկրտությունից հետո","why":"«Դրոշմ» և «կնունք» բառերը նշանակում են «կնիք»։ Սուրբ Հոգու շնորհը ամրացնում է հոգին և քաջություն տալիս կյանքի դժվարությունների դեմ։"},{"id":"apashkharutyun","title":"Ապաշխարություն (խոստովանություն)","text":"Այս խորհրդում մարդը խոստովանում է իր մեղքերը Աստծո և Եկեղեցու առջև և քահանայի միջոցով Քրիստոսից ստանում մեղքերի թողություն։ Խոստովանության ժամանակ կարդացվում է «Զղջում» կոչվող մեղաների շարքը։\nԿա ընդհանուր խոստովանություն, որ Պատարագից առաջ կարդում են քահանան և հավատացյալները միասին, և անձնական խոստովանություն՝ քահանայի մոտ։ Խորհրդին պատրաստվում են պահեցողությամբ և աղոթքով։","when":"Երբ զղջում ենք մեր մեղքերի համար, և Հաղորդությունից առաջ","why":"Ապաշխարելը նշանակում է ոչ միայն զղջալ, այլև կյանքը ճիշտ ուղու վրա դնել՝ հավատալով Քրիստոսին և հուսալով Նրա ողորմությանը։"},{"id":"haghordutyun","title":"Հաղորդություն","text":"Հաղորդության խորհրդով հավատացյալը հացի և գինու տեսքով ստանում է Քրիստոսի Մարմինն ու Արյունը՝ մեղքերի թողության և հավիտենական կյանքի համար։\nԻնչպես պատրաստվել և ինչպես ստանալ Հաղորդությունը՝ տես «Վարք եկեղեցում» բաժնի «Պատարագ և Հաղորդություն» թեման։","when":"Սուրբ Պատարագի ժամանակ","why":"Վերջին ընթրիքին Քրիստոս վերցրեց հացը, օրհնեց, մասնատեց և տվեց աշակերտներին՝ ասելով. «Առե՛ք, կերե՛ք, այս է իմ մարմինը», իսկ բաժակի համար՝ «Խմեցե՛ք դրանից բոլորդ, որովհետև այդ է նոր ուխտի իմ արյունը» (Մատթ. 26.26–28)։ Եվ պատվիրեց միշտ կատարել այս խորհուրդը։"},{"id":"psak","title":"Պսակ","text":"Պսակը տղամարդու և կնոջ միության օրհնությունն է. նրանք փոխադարձ համաձայնությամբ միանում են միմյանց և Եկեղեցուն հոգևոր կապով։\nՔահանան օրհնում է մատանիները և միացնում հարսի ու փեսայի աջ ձեռքերը, երեք անգամ հարցնում, թե արդյոք նրանք հավատարիմ կլինեն միմյանց մինչև կյանքի վերջ։ Ընթերցվում են Եփեսացիներին 5.22–33-ը և Ավետարանից Մատթեոս 19-ը։ Հետո քահանան պսակներ է դնում նրանց գլխին (դրանք հիշեցնում են Տրդատ թագավորին և Աշխեն թագուհուն), իսկ խաչեղբայրը խաչը պահում է նրանց գլխավերևում։ Վերջում զույգը ճաշակում է օրհնված գինի՝ ի հիշատակ Կանայի հարսանիքի։","when":"Ամուսնանալիս","why":"Քրիստոս Իր ներկայությամբ օրհնեց Կանայի հարսանիքը (Հովհ. 2.1–11) և ասաց. «Ինչ որ Աստված միացրեց, մարդը թող չբաժանի» (Մատթ. 19.6)։"},{"id":"karg-hivandats","title":"Կարգ հիվանդաց","text":"Սա հիվանդների բժշկության խորհուրդն է, հաստատված դեռ առաքյալների ժամանակ։ Այն մահվան նախապատրաստություն չէ, ինչպես երբեմն կարծում են։\nԱյսօր քահանան այցելում է հիվանդին, աղոթում, կարդում բժշկության Ավետարանը, աջը դնում նրա վրա և տալիս Հաղորդություն, որ բժշկություն գտնեն թե՛ հոգին, թե՛ մարմինը։","when":"Երբ մարդը հիվանդ է","why":"Հակոբոս առաքյալը գրում է. «Հիվա՛նդ է ձեզանից մեկը, թող կանչի եկեղեցու երեցներին, և նրանք նրա վրա թող աղոթք անեն, թող յուղով օծեն նրան Տիրոջ անունով» (Հակ. 5.14)։"},{"id":"dzernadrutyun","title":"Ձեռնադրություն","text":"Ձեռնադրությամբ մարդը ստանում է Եկեղեցում ծառայելու, խորհուրդները կատարելու և հավատացյալներին ուսուցանելու իշխանությունն ու շնորհը։ Այս իշխանությունը չի տրվում ընտրությամբ կամ նշանակմամբ, այլ միայն Ձեռնադրության խորհրդով։\nՁեռնադրությունը միշտ կատարում է եպիսկոպոսը՝ իր աջը դնելով ընծայացուի գլխին։ Եպիսկոպոսին օծում է կաթողիկոսը՝ առնվազն երկու եպիսկոպոսի մասնակցությամբ։ Ձեռնադրության ժամանակ երգչախումբը երգում է «Արժանի է»՝ ժողովրդի համաձայնության նշան։","when":"Երբ մարդը կոչվում է Եկեղեցու ծառայության","why":"Եպիսկոպոսի աջով շարունակվում է այն հաջորդականությունը, որ սկսվել է առաքյալներից և անընդհատ հասել է մինչև մեզ։ Մկրտությամբ բոլոր քրիստոնյաները կոչված են աղոթքով և բարի գործերով ծառայելու Աստծուն, իսկ խորհուրդները կատարելու շնորհը տրվում է Ձեռնադրությամբ։"}],"faq":[]}', '["Վրաստանի հայոց թեմ, «Խորհուրդներ» գրքույկներ (armenianchurch.ge)"]', 'review', 20);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('remembrance', 'Հիշատակության օրեր', 'Այգուց, յոթնօրեք, քառասունք, տարելից, հոգեհանգիստ', 'Եկեղեցին ննջեցյալներին հիշում է աղոթքով, Պատարագով և հոգեհանգստով։ Հիշատակության հիմնական օրերն են՝ Այգուց, Յոթնօրեք, Քառասունք և Տարելից։', 'guide', '', 'flower', '{"blocks":[{"id":"aygots","title":"Այգուց","text":"Թաղման երկրորդ օրը առավոտյան հարազատները գնում են գերեզման՝ հանգուցյալին հիշելու։ Հին ձեռագրերում այն կոչվում էր նաև «այգալույս»։","when":"Թաղման հաջորդ առավոտը","why":"Ինչպես յուղաբեր կանայք առավոտյան գնացին Քրիստոսի գերեզմանը և տեսան Նրան հարություն առած։ Գրիգոր Տաթևացու խոսքով՝ երեկ սգացինք, իսկ այսօր գալիս ենք մխիթարված և գոհություն ենք հայտնում Աստծուն։"},{"id":"yotnorek","title":"Յոթնօրեք","text":"Այցելում են շիրիմը և աղոթում հանգուցյալի հոգու համար։ Աղոթքներում խնդրում ենք, որ Տերը նրա հոգին հանգստացնի արդարների կայաններում, և դատաստանի օրը նա չամաչի։","when":"Թաղման օրից հաշված 7-րդ օրը","why":"Աստված վեց օրում ստեղծեց աշխարհը, իսկ յոթերորդ օրը հանգստացավ (Ծննդ. 2.2–3)։ Յոթերորդ օրը խորհրդանշում է հոգու հավիտենական հանգիստը Աստծո արքայության մեջ։"},{"id":"karasunk","title":"Քառասունք","text":"Այս օրը կատարվում է հոգեհանգիստ։ Քառասուն օրերի ընթացքում հարազատները աղոթքում հիշում են հանգուցյալին և նրա անունից ողորմություն բաժանում։","when":"Մահվան օրից հաշված 40-րդ օրը (մահվան օրը՝ առաջինը)","why":"Քրիստոս Հարությունից հետո քառասուն օր մնաց երկրի վրա, ապա համբարձվեց։ Եկեղեցական ավանդության համաձայն՝ քառասուներորդ օրը հոգին իմանում է իր օթևանը՝ մինչև Քրիստոսի երկրորդ գալուստը։"},{"id":"tarelits","title":"Տարելից","text":"Լավ է պատվիրել հոգեհանգիստ, քահանա հրավիրել գերեզման և աղոթքներով խնկարկել շիրիմը։","when":"Մահվան օրից մեկ տարի անց","why":"Եկեղեցին հիշում է ոչ թե ծննդյան, այլ մահվան օրը, որովհետև մահվան օրը համարվում է իսկական ծնունդ՝ նոր կյանքում, Քրիստոսի մոտ։"},{"id":"hogehangist","title":"Հոգեհանգիստ","text":"Ննջեցյալների համար կատարվող աղոթքի կարգ է։ Կարելի է պատվիրել եկեղեցում՝ յոթնօրեքին, քառասունքին, տարելիցին։ Տաղավար տոներից հետո՝ Մեռելոցին, Եկեղեցին հիշում է բոլոր ննջեցյալներին։","when":"Հիշատակության օրերին, հաճախ՝ Սուրբ Պատարագի վերջում"}],"faq":[{"q":"Ինչպե՞ս հաշվել քառասունքը","a":"Մահվան օրը համարվում է առաջին օրը, և քառասուներորդ օրը նշվում է քառասունքը։"},{"q":"Յոթնօրեքը ո՞ր օրվանից են հաշվում","a":"Թաղման օրից։"}]}', '["Գևորգ սրկ. Գևորգյան, «Ի՞նչ են հանգուցյալի հիշատակության օրերի իմաստները», Հյուսիսային Ամերիկայի Արևմտյան թեմ, 2022","Միքայել սրկ. Մարգարյան, «Ժամերգություններ»"]', 'review', 30);
